import{_ as l,o as i,c as e,ag as t}from"./chunks/framework.QfQ7DfGu.js";const u=JSON.parse('{"title":"2K1000LA开发板平台","description":"","frontmatter":{"title":"2K1000LA开发板平台","outline":"deep"},"headers":[],"relativePath":"platform/2k1000la.md","filePath":"platform/2k1000la.md"}'),o={name:"platform/2k1000la.md"};function r(n,a,p,s,h,d){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="_2k1000la星云板" tabindex="-1"><strong>2K1000LA星云板</strong> <a class="header-anchor" href="#_2k1000la星云板" aria-label="Permalink to &quot;**2K1000LA星云板**&quot;">​</a></h1><p>广东龙芯2K1000星云板基于龙芯2K1000处理器，采用单板的方式设计。该开发板主要包含CPU、内存、双网口、USB、RS232、RS485、CAN等主要芯片及常用外设接口，同时通过插针形式的引出其他接口。</p><p>本板卡采用标准化贴片焊接工艺，接口丰富，具有稳定、安全、可靠等特点，可广泛应用于国防、电力、交通、医疗、金融、通信、能源等行业领域。</p><p>点击该<a href="https://github.com/LoongsonLab/oscomp-documents/blob/main/pdf/%E5%B9%BF%E4%B8%9C%E9%BE%99%E8%8A%AF2K1000%E6%98%9F%E4%BA%91%E6%9D%BF%E7%94%A8%E6%88%B7%E6%89%8B%E5%86%8CV1.1.pdf" target="_blank" rel="noreferrer">文档</a>查看。</p><h2 id="板卡硬件资源" tabindex="-1">板卡硬件资源 <a class="header-anchor" href="#板卡硬件资源" aria-label="Permalink to &quot;板卡硬件资源&quot;">​</a></h2><p>2K1000LA支持硬件资源，包括:</p><ul><li>2K1000LA 双核CPU，800 MHz - 1000 MHz</li><li>1 GB DDR3 内存</li><li>32 GB SSD(M.2 2242) 存储</li><li>2 路千兆 Rj45</li><li>2 路 USB2.0 HOST，其中一路与4G模块接口复用</li><li>1 路 LCD 接口（支持 24 位输出）</li><li>1 个 MicroUSB</li><li>1 路 4G 模块接口</li><li>1 路 SPI接口</li><li>2 路 I2C接口</li></ul><h2 id="开发环境" tabindex="-1">开发环境 <a class="header-anchor" href="#开发环境" aria-label="Permalink to &quot;开发环境&quot;">​</a></h2><h3 id="u-boot" tabindex="-1">U-Boot <a class="header-anchor" href="#u-boot" aria-label="Permalink to &quot;U-Boot&quot;">​</a></h3><p>2K1000LA 星云板提供基于 U-Boot-2022.04 移植开发。</p><p>文档附有详细编译教程。</p><h3 id="linux" tabindex="-1">linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;linux&quot;">​</a></h3><p>2K1000LA 星云板提供基于 linux-5.10.0 移植开发。</p><p>文档附有详细编译教程。</p><p>上述详细文件，在下方链接。</p><p>链接：<a href="https://pan.baidu.com/s/1QDnNmmc7iTCeG0vEJl5ihA" target="_blank" rel="noreferrer">https://pan.baidu.com/s/1QDnNmmc7iTCeG0vEJl5ihA</a></p><p>提取码：0amv</p><p>资料包含有：</p><ul><li>开发板原理图</li><li>固件源码，与编译好的二进制文件</li><li>内核源码，与编译好的二进制文件</li><li>交叉编译器</li><li>虚拟机环境</li><li>视频教程</li></ul>',19)])])}const m=l(o,[["render",r]]);export{u as __pageData,m as default};
